  {label:'Личный план',value:target===undefined?'Нет данных':target===null?'Не задан':stale===true?'Нужен пересмотр':held===true?'Приостановлен':stale===false&&held===false?'Ориентиры сохранены':'Статус не уточнён',note:'Ориентиры питания, не оценка здоровья.',view:'targets',icon:'plan'},
  {label:'Мои запасы',value:pantry===null?'Нет данных':String(pantry.length),note:pantry===null?'Состав запасов не получен.':'Сохранённых позиций. Масса может быть неизвестна.',view:'recipes',icon:'pantry'},
  {label:'Дневник',value:diary===null?'Нет данных':String(diary.length),note:diary===null?'Записи не получены.':'Сохранённых записей. Это не сумма потребления.',view:'diary',icon:'diary'}
