function renderTranquilSummary(next){
 const host=$('dawn-overview'),cards=$('dawn-status-cards'),progress=$('dawn-progress');
 cards.replaceChildren();progress.replaceChildren();host.hidden=true;
 const summary=tranquilSummary(next);if(!summary)return;
 const symbols={profile:'profile',plan:'plan',pantry:'basket',diary:'note'};
 for(const item of summary.cards){
  const card=el('article','dawn-status-card'),badge=el('span','dawn-status-icon');badge.setAttribute('data-icon',symbols[item.icon]);badge.setAttribute('aria-hidden','true');
  const button=el('button','','Открыть');button.type='button';button.dataset.view=item.view;button.setAttribute('aria-label','Открыть: '+item.label);button.onclick=()=>setView(item.view);
  card.append(badge,el('h3','',item.label),el('p','dawn-status-value',item.value),el('p','dawn-status-note',item.note),button);cards.append(card);
 }
 const text=el('p','','Подготовка личного меню: '+summary.completed+' из '+summary.steps.length+' этапов'),bar=el('progress');bar.max=summary.steps.length;bar.value=summary.completed;bar.setAttribute('aria-label',text.textContent);
 const list=el('ol');for(const [label,done]of summary.steps)list.append(el('li','',label+' · '+(done?'готово':'не завершено или не подтверждено')));
 progress.append(text,bar,list);host.hidden=false;
}
