async function propose(type,payload,expectedRevision=state.revision){const r=await call('keto_propose_change',{event_type:type,payload,expected_revision:expectedRevision});accept(r);return r;}
function recipeCard(r){const b=el('button','recipe-card');b.append(el('span','tag',({breakfast:'Завтрак',main:'Основное блюдо',side:'Гарнир',component:'Компонент'})[r.category]||'Блюдо'),el('h3','',r.name_ru));const meta=el('div','recipe-meta');meta.append(el('span','',r.active_minutes+' мин'),el('span','nutrition',numberRu(r.nutrition.energy_kcal,0)+' ккал · расчёт'));if(r.fit_note)b.append(el('p','muted',r.fit_note));b.append(meta,el('span','open','Ингредиенты и шаги →'));b.addEventListener('click',()=>openRecipe(r));return b;}
function openRecipe(r,originSource=null){const box=$('recipe-detail');box.replaceChildren(el('span','eyebrow','РЕЦЕПТ · '+r.active_minutes+' МИН'),el('h2','',r.name_ru));if(r.fit_note)box.append(el('p','notice',r.fit_note));const record=el('button','primary','Записать съеденное');record.type='button';record.onclick=()=>intake.open({recipe_id:r.recipe_id,name_ru:r.name_ru,amount:{value:Number.isFinite(r.portions)?r.portions:1,unit:'portion'},thread_id:originSource?.thread_id||state.active_thread||'main',origin:originSource?.origin,generation_id:originSource?.generation_id||r.generation_id});box.append(record);const list=el('ul','ingredient-list');for(const i of r.ingredients){const li=el('li');li.append(el('span','',i.name_ru+' · '+foodState(i.state)+''),el('strong','',numberRu(i.grams_edible)+' г'));list.append(li);}box.append(list);const steps=el('ol','steps');const source=Array.isArray(r.steps_ru)?r.steps_ru:[r.steps_ru];for(const st of source)steps.append(el('li','',st));box.append(steps,el('p','nutrition muted',`Расчёт на ${numberRu(Number.isFinite(r.portions)?r.portions:1)} порции: ${numberRu(r.nutrition.energy_kcal,0)} ккал; белок ${numberRu(r.nutrition.protein_g)} г; общие углеводы ${numberRu(r.nutrition.carbohydrate_total_g)} г. Отсутствующие нутриенты не считаются нулём.`),el('p','muted','Аллергены: '+(r.allergens.map(x=>ALLERGENS.find(a=>a[0]===x)?.[1]||'уточните состав').join(', ')||'не отмечены в справочнике; проверьте этикетки')+'. Рецептура не прошла кухонное тестирование.'));const fav=el('button','secondary','Понравилось');fav.addEventListener('click',()=>run(async()=>{await propose('feedback.add',{recipe_id:r.recipe_id,rating:5,would_repeat:true});}));box.append(fav);dialogs.open('recipe','recipe-close-top');}
const recipeLibrary=createRecipeLibrary({clear:()=>$('recipes').replaceChildren(),call:args=>recipePageCall('keto_recipes',args),readFilters:()=>{const args={query:$('recipe-query').value};if($('recipe-category').value)args.category=$('recipe-category').value;if($('recipe-minutes').value)args.max_minutes=Number($('recipe-minutes').value);return args},epoch:()=>screenEpoch,status:t=>$('recipe-note').textContent=t,more:(show,retry)=>{$('recipe-more').hidden=!show;$('recipe-more').textContent=retry?'Повторить загрузку':'Показать ещё'},render:(d,append)=>{const cards=d.recipes.map(r=>r.draft_label?kitchen.card(r):recipeCard(r));if(append)$('recipes').append(...cards);else $('recipes').replaceChildren(...cards);if(!d.total)$('recipes').append(el('div','panel','Не нашлось совпадения. Измените поиск или фильтры.'))}});
async function loadRecipes(){return recipeLibrary.load(false)}

function renderDiary(){intake.render();}
function renderHistory(){$('history').replaceChildren();if(!state.ui_history.length)$('history').append(el('p','muted','Пока оформление не менялось.'));for(const x of [...state.ui_history].reverse()){const b=el('button','secondary','Вернуть вид до '+new Date(x.at).toLocaleTimeString('ru',{hour:'2-digit',minute:'2-digit'}));b.addEventListener('click',()=>run(()=>propose('ui.rollback',{history_id:x.id})));$('history').append(b);}}
function fillSettings(){if(!state)return;for(const [key,value]of Object.entries(state.ui)){const input=$(key);if(input)input.type==='checkbox'?input.checked=value:input.value=value;}for(const key of ['meals_per_day','max_active_minutes'])$(key).value=state.profile.settings[key];}
function renderPlan(plan,draft=true){currentPlan=plan;currentPlanIsDraft=draft;renderTodayPlan({plan,draft,root:$('menu-result'),empty:$('today-empty'),el,formatDate,openRecipe,acceptPlan:()=>run(()=>propose('plan.accept',plan))});}
function renderShopping(items){const root=$('menu-result'),box=el('div','panel');box.append(el('h2','','Список покупок'),el('p','muted','Указана масса съедобной части; проверьте состояние продуктов.'));const list=el('ul');for(const i of items)list.append(el('li','',i.name_ru+' — '+(i.stock_quantity_unknown?'нужно '+numberRu(i.required_grams)+' г; уточните запас':numberRu(i.grams_edible)+' г')+' · '+foodState(i.state)));box.append(list);root.append(box);}
function fillOnboard(){if(!state)return;const p=state.profile;screenDraft={...p.screening};const unanswered=QUESTIONS.findIndex(([key])=>p.screening[key]===null||p.screening[key]===undefined||(['medications_reviewed','allergies_reviewed'].includes(key)&&p.screening[key]!==true));questionPage=Math.max(0,unanswered);$('display-name').value=p.display_name||'';$('goal').value=p.goal||'';$('timezone').value=p.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'';$('medications').value=p.medications.map(x=>x.name).join(', ');$('allergy-options').replaceChildren();for(const [id,name]of [...ALLERGENS,...p.allergies.filter(id=>!ALLERGENS.some(a=>a[0]===id)).map(id=>[id,'Сохранённое ограничение: '+id])]){const label=el('label','check'),i=document.createElement('input');i.type='checkbox';i.value=id;i.checked=p.allergies.includes(id);label.append(i,el('span','',name));$('allergy-options').append(label);}renderQuestions();}
function renderQuestions(){const start=questionPage;$('question-progress').textContent=`Вопрос ${start+1} из ${QUESTIONS.length}`;$('screen-questions').replaceChildren();for(const [key,label]of QUESTIONS.slice(start,start+1)){const lab=el('label','',label),sel=el('select');sel.dataset.screen=key;sel.setAttribute('aria-label',label);for(const[v,t]of [['unknown','Не знаю / ещё не ответила'],['yes','Да'],['no','Нет']]){const o=el('option','',t);o.value=v;sel.append(o);}sel.value=screenDraft[key]===true?'yes':screenDraft[key]===false?'no':'unknown';sel.addEventListener('change',()=>screenDraft[key]=sel.value==='unknown'?null:sel.value==='yes');const hint=el('small','field-help',key==='adult'?'Персональное меню доступно только после подтверждения совершеннолетия.':'Ответ влияет на ограничения персонального меню. «Не знаю» оставляет вопрос открытым, не считается ответом «нет».');hint.id='question-help-'+key;sel.setAttribute('aria-describedby',hint.id);lab.append(sel,hint);$('screen-questions').append(lab);}$('question-prev').disabled=questionPage===0;$('question-next').disabled=start+1>=QUESTIONS.length;}
function markSafetyHold(d){if(!d?.safety_hold)return;if(state)state.holds=[...new Set([...(state.holds||[]),...d.safety_hold])];currentPlan=null;$('menu-result').replaceChildren(el('div','notice danger','Меню приостановлено из-за нового ограничения.'));}
