function glucoseUnitLabel(unit){return unit==='mg/dL'?'мг/дл':'ммоль/л';}
function measurementTimeLabel(m){try{return new Intl.DateTimeFormat('ru-RU',{timeZone:m.timezone,year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(m.measured_at));}catch{return m.measured_at;}}
const measurementSubmissions=new Map();
const measurementFields=['measurement-time','measurement-glucose','measurement-unit','measurement-bhb','measurement-context'];
function measurementDraft(){return {editing:measurementEditing,original:measurementOriginal,fields:measurementFields.map(id=>$(id).value)};}
function restoreMeasurementDraft(d){measurementEditing=d?.editing||null;measurementOriginal=d?.original||null;if(d)measurementFields.forEach((id,i)=>$(id).value=d.fields[i]);else $('measurement-form').reset();$('measurement-cancel').hidden=!measurementEditing;$('measurement-zone').textContent='Часовой пояс устройства: '+Intl.DateTimeFormat().resolvedOptions().timeZone;}
function draftFingerprint(){return JSON.stringify(measurementDraft());}
function finishMeasurementReceipt(p){const fp=measurementSubmissions.get(p.id);measurementSubmissions.delete(p.id);if(fp!==undefined&&fp===draftFingerprint()){const saved=measurementSavedDraft;measurementSavedDraft=null;restoreMeasurementDraft(saved);}}
function measurementPreview(p){const m=p.type==='measurement.update'?p.payload.session:p.type==='measurement.delete'?(state.measurements||[]).find(x=>x.measurement_id===p.payload.measurement_id):p.payload;if(!m)return [['Измерение','Не найдено']];return [['Дата и время',measurementTimeLabel(m)],['Часовой пояс',m.timezone],['Глюкоза',m.glucose?numberRu(m.glucose.value)+' '+glucoseUnitLabel(m.glucose.unit):'не указана'],['BHB крови',m.bhb?numberRu(m.bhb.value)+' ммоль/л':'не указан'],['Контекст',m.context||'не указан']];}
function readDecimal(id){const v=$(id).value.trim();if(!v)return null;if(!/^\d+(?:[.,]\d+)?$/.test(v))throw Error('Введите неотрицательное число.');const n=Number(v.replace(',','.'));if(!Number.isFinite(n))throw Error('Неверное число.');return n;}
function renderMeasurements(){const box=$('measurement-list');box.replaceChildren();if(!Array.isArray(state.measurements))box.append(el('p','muted','Измерения не получены.'));else if(!state.measurements.length)box.append(el('p','muted','Измерений пока нет.'));for(const m of [...(state.measurements||[])].reverse()){const card=el('article','diary-entry');card.append(el('p','',measurementTimeLabel(m)+' · '+m.timezone),el('p','',`Глюкоза: ${m.glucose?numberRu(m.glucose.value)+' '+glucoseUnitLabel(m.glucose.unit):'не указана'} · BHB крови: ${m.bhb?numberRu(m.bhb.value)+' ммоль/л':'не указан'}`),el('p','',m.gki?.value==null?m.gki?.reason:'GKI: '+numberRu(m.gki.value,2)),...(m.context?[el('p','muted',m.context)]:[]));const edit=el('button','','Исправить'),del=el('button','text-btn','Удалить');edit.type=del.type='button';edit.onclick=()=>{if(measurementEditing){notify('Сначала завершите или отмените текущее исправление.');return;}measurementSavedDraft=measurementDraft();measurementEditing=m.measurement_id;measurementOriginal={measured_at:m.measured_at,timezone:m.timezone,display:m.measured_at.slice(0,16)};$('measurement-time').value=measurementOriginal.display;$('measurement-glucose').value=m.glucose?.value??'';$('measurement-unit').value=m.glucose?.unit||'mmol/L';$('measurement-bhb').value=m.bhb?.value??'';$('measurement-context').value=m.context||'';$('measurement-zone').textContent='Исходный часовой пояс: '+m.timezone+'. Если изменить время, будет использован часовой пояс устройства.';$('measurement-cancel').hidden=false;};del.onclick=()=>run(()=>propose('measurement.delete',{measurement_id:m.measurement_id}));card.append(edit,del);box.append(card);}}
$('measurement-zone').textContent='Часовой пояс устройства: '+Intl.DateTimeFormat().resolvedOptions().timeZone;
$('measurement-cancel').onclick=()=>{const saved=measurementSavedDraft;measurementSavedDraft=null;restoreMeasurementDraft(saved);};
$('measurement-form').onsubmit=e=>{e.preventDefault();run(async()=>{const raw=$('measurement-time').value;let m;if(measurementOriginal&&raw===measurementOriginal.display){m={measured_at:measurementOriginal.measured_at,timezone:measurementOriginal.timezone};}else{const dt=new Date(raw);if(!raw||!Number.isFinite(dt.getTime()))throw Error('Укажите дату и время.');const local=[dt.getFullYear(),String(dt.getMonth()+1).padStart(2,'0'),String(dt.getDate()).padStart(2,'0')].join('-')+'T'+[dt.getHours(),dt.getMinutes()].map(n=>String(n).padStart(2,'0')).join(':');if(local!==raw)throw Error('Это местное время не существует при переводе часов; выберите другое время.');const offset=-dt.getTimezoneOffset(),sign=offset>=0?'+':'-',pad=n=>String(Math.abs(n)).padStart(2,'0');m={measured_at:raw+':00'+sign+pad(Math.trunc(offset/60))+':'+pad(offset%60),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone};}const g=readDecimal('measurement-glucose'),b=readDecimal('measurement-bhb');if(g!==null)m.glucose={value:g,unit:$('measurement-unit').value};if(b!==null)m.bhb={value:b,unit:'mmol/L'};if(g===null&&b===null)throw Error('Укажите хотя бы одно измерение.');if($('measurement-context').value.trim())m.context=$('measurement-context').value.trim();const fingerprint=draftFingerprint();const r=await propose(measurementEditing?'measurement.update':'measurement.add',measurementEditing?{measurement_id:measurementEditing,session:m}:m);if(r?.proposal?.id)measurementSubmissions.set(r.proposal.id,fingerprint);});};
