async function cfApi(path,{method='GET',body}={}){const epoch=screenEpoch;const r=await fetch(path,{method,headers:{...(body?{'Content-Type':'application/json'}:{}),...(session&&method!=='GET'?{'X-CSRF-Token':session.csrf}:{})},body:body?JSON.stringify(body):undefined});const d=await r.json();if(epoch!==screenEpoch)throw Error('Сеанс изменился. Обновите экран.');if(!r.ok)throw Error(({SETUP_REQUIRED:'Вход пока не настроен.',INVITATION_REQUIRED:'Нужно действующее приглашение для этой почты.',INVITE_NOT_AVAILABLE:'Приглашение недоступно.',CONSENT_REQUIRED:'Сначала разрешите хранение.',IMAGE_PROCESSING_UNAVAILABLE:'Проверка изображения недоступна.',TOO_LARGE:'Файл слишком большой.',DEVELOPER_NOT_CONFIGURED:'Раннер или исходный snapshot не настроен.',DEVELOPER_QUOTA_OR_REPLAY:'Лимит генераций исчерпан или запрос уже выполнялся.',DEVELOPER_GENERATION_OR_TEST_FAILED:'Генерация или проверка не прошла. Разрешены только стили, справка и UI-расширение; серверные изменения требуют отдельной задачи.',DEVELOPER_BUSY_OR_DISABLED:'Пилот выключен или другая задача ещё открыта.',DEVELOPER_CANCELLED_OR_EXPIRED:'Задача отменена или срок истёк.',IMAGE_LINK_UNSUPPORTED:'Этот адрес не поддерживается. Прикрепите файл, скриншот или текст страницы.',IMAGE_LINK_PRIVATE_QUERY:'Ссылка содержит неподдерживаемые параметры. Скачайте фото и прикрепите файл.',IMAGE_UPLOAD_REQUIRED:'Для этого размера скачайте фото и прикрепите файл: приложение сожмёт его перед отправкой.',IMAGE_NOT_DIRECT:'Ссылка ведёт не на изображение. Прикрепите файл или скриншот.',IMAGE_DNS_REJECTED:'Адрес изображения не прошёл проверку. Прикрепите файл.',IMAGE_TOO_LARGE:'Фото больше 4 МБ. Прикрепите файл для локального сжатия.'})[d.error]||'Действие не выполнено.');return d}
$('source-form').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target),file=f.get('upload');let upload;if(file?.size){if(file.size>512000||(file.type==='text/plain'&&file.size>4000))throw Error('Файл слишком большой.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(const b of bytes)binary+=String.fromCharCode(b);upload={mime:file.type||'text/plain',data:btoa(binary).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'')}}await cfApi('/api/sources',{method:'POST',body:{title:f.get('title'),author:f.get('author'),url:f.get('url'),text:f.get('text'),rights_attested:f.get('rights')==='on',...(upload?{upload}:{})}});e.target.reset();await sources();notify('Источник сохранён для личного просмотра.')})};
async function sources(){const d=await cfApi('/api/sources'),box=$('source-list');box.replaceChildren();for(const s of d.sources){const card=document.createElement('article');card.className='source';const title=document.createElement('h3');title.textContent=s.title;const text=document.createElement('p');text.textContent=(s.author?s.author+' · ':'')+({needs_content:'Нужен текст или доступ',draft:'Черновик',reviewed:'Просмотрено',personal_recipe:'Личный рецепт сохранён'})[s.status]+'\n'+s.excerpt;card.append(title,text);if(s.mime){let a=document.createElement('a');a.href='/api/sources/file?id='+encodeURIComponent(s.id);a.textContent='Скачать файл';card.append(a)}const del=document.createElement('button');del.textContent='Удалить';del.onclick=()=>run(async()=>{await cfApi('/api/sources/delete',{method:'POST',body:{id:s.id}});await sources()});card.append(del);if(s.status!=='needs_content'){const discuss=el('button','secondary','Обсудить');discuss.onclick=()=>{attachedSource=s.id;setView('chat');$('message').value='Обсуди этот источник';$('message').focus();notify('Источник прикреплён к следующему сообщению.');};card.append(discuss);const recipe=el('button','secondary','Подготовить рецепт');recipe.onclick=()=>{recipeSource=s.id;$('source-recipe-form').reset();dialogs.open('source','sr-name')};card.append(recipe);if(s.status==='draft'){const review=el('button','secondary','Отметить просмотренным');review.onclick=()=>run(async()=>{await cfApi('/api/sources/review',{method:'POST',body:{id:s.id,reviewed:true}});await sources()});card.append(review);}}box.append(card)}}
$('invite-form').onsubmit=e=>{e.preventDefault();run(async()=>{const d=await cfApi('/api/admin/invites',{method:'POST',body:{email:new FormData(e.target).get('email')}});$('invite-link').textContent='Ссылка показывается один раз: '+d.link;await admin()})};
async function admin(){const d=await cfApi('/api/admin/summary'),box=$('admin-summary');box.replaceChildren();let counts=document.createElement('p');counts.textContent=`Активны: ${d.active}, ожидают: ${d.pending}, истекли: ${d.expired}`;box.append(counts);for(const m of d.members){let row=document.createElement('div');row.className='member';row.textContent=`${m.email} · ${m.status} · присоединился: ${new Date(m.joined_at*1000).toLocaleDateString('ru')} · последний вход: ${new Date(m.last_active*1000).toLocaleDateString('ru')} · запросов: ${m.requests} `;if(m.role==='member'&&m.status!=='pending'){let b=document.createElement('button');b.textContent=m.status==='active'?'Приостановить':'Восстановить';b.onclick=()=>run(async()=>{await cfApi('/api/admin/members/status',{method:'POST',body:{id:m.id,status:m.status==='active'?'suspended':'active'}});await admin()});row.append(b)}box.append(row)}for(const i of d.invites){if(!i.revoked_at&&!i.claimed_by&&i.expires_at>Date.now()/1000){let row=document.createElement('div');row.className='member';row.textContent='Приглашение: '+i.email+' ';let b=document.createElement('button');b.textContent='Отозвать';b.onclick=()=>run(async()=>{await cfApi('/api/admin/invites/revoke',{method:'POST',body:{id:i.id}});await admin()});row.append(b);box.append(row)}}}
$('sr-close').onclick=()=>dialogs.close();
$('source-recipe-form').onsubmit=e=>{e.preventDefault();run(async()=>{if(!recipeSource)throw Error('Выберите источник.');const states={'сырой':'raw','готовый':'ready_to_eat','запечённый':'cooked_roasted','варёный':'cooked_boiled','сухой':'dry','консервированный':'canned','без жидкости':'canned_drained','готовить':'ready_to_cook','сухой жар':'cooked_dry_heat','приготовленный':'cooked'};const ingredients=$('sr-ingredients').value.split('\n').map(line=>line.trim()).filter(Boolean).map(line=>{const parts=line.split(';').map(x=>x.trim());const grams=Number((parts[1]||'').replace(',','.')),st=states[(parts[2]||'').toLowerCase()];if(parts.length!==3||!/^[FU][A-Za-z0-9_-]+$/.test(parts[0])||!Number.isFinite(grams)||grams<=0||!st)throw Error('Проверьте каждую строку: код; граммы; состояние.');return {food_id:parts[0],grams_edible:grams,state:st}});if(!ingredients.length||ingredients.length>20)throw Error('Укажите от 1 до 20 ингредиентов.');const payload={recipe_id:'R'+crypto.randomUUID().replaceAll('-',''),name_ru:$('sr-name').value,category:$('sr-category').value,protein_family:'other',base_servings:Number($('sr-servings').value),active_minutes:Number($('sr-minutes').value),ingredients,steps_ru:$('sr-steps').value};const d=await call('keto_propose_change',{event_type:'catalog.recipe.add',payload,expected_revision:state.revision,source_id:recipeSource});$('source-recipe-dialog').close();accept(d);})};
$('cf-login').onclick=()=>run(async()=>{if(!loginConfig)throw Error('Вход пока не настроен. Обновите страницу.');const invite=sessionStorage.getItem('keto_invite')||'';if(loginConfig.provider==='firebase_google'){await firebaseLogin(loginConfig.firebase,invite,(path,body)=>cfApi(path,{method:'POST',body}));await start();return}if(loginConfig.provider==='direct_google'){const d=await cfApi('/auth/google/start',{method:'POST',body:{invite}});location.assign(d.authorization_url);return}throw Error('Вход пока не настроен.')});
$('cf-claim-button').onclick=()=>run(async()=>{await cfApi('/api/invites/claim',{method:'POST',body:{token:sessionStorage.getItem('keto_invite')||''}});sessionStorage.removeItem('keto_invite');await start()});
$('cf-switch').onclick=()=>run(async()=>{await cfApi('/api/logout',{method:'POST',body:{}});session=null;showLogin()});
$('continue-deletion').onclick=()=>run(async()=>{const receipt=sessionStorage.getItem('keto_deletion_receipt')||$('deletion-code').value.trim();if(!receipt){$('deletion-status').textContent='Введите сохранённый код удаления.';return;}const d=await cfApi('/api/deletion/continue',{method:'POST',body:{receipt}});$('deletion-status').textContent=d.status==='complete'?'Активные данные удалены. Политика резервных копий отдельная.':'Удаление продолжается; повторите проверку позже. Код: '+receipt;if(d.status==='complete')sessionStorage.removeItem('keto_deletion_receipt')});
async function start(){const url=new URL(location.href),incoming=url.searchParams.get('invite');if(incoming){sessionStorage.setItem('keto_invite',incoming);url.searchParams.delete('invite');history.replaceState(null,'',url.pathname+url.search+url.hash)}$('deletion-code').value=sessionStorage.getItem('keto_deletion_receipt')||'';try{const r=await fetch('/auth/config');loginConfig=r.ok?await r.json():null}catch{loginConfig=null}try{session=await cfApi('/api/session');csrf=session.csrf;if(session.user.status==='pending'){showLogin();$('cf-claim').hidden=false;$('cf-login-message').textContent='Аккаунт: '+session.user.email;return}$('cf-claim').hidden=true;$('admin-tab').hidden=session.user.role!=='admin';developer.identity();await refresh();setView(guided.initial(state,location.hash),{replace:true,reason:'initial'})}catch(e){session=null;showLogin();$('cf-login-message').textContent=e.message}}
const mobile=setupMobile({$,el,call,accept,getState:()=>state,setView,run,notify,openDialog:(kind,focus)=>dialogs.open(kind,focus),closeDialog:()=>dialogs.close(),epoch:()=>screenEpoch,setImage:value=>image=value,getImage:()=>image,loadImageLink:async url=>(await cfApi('/api/media/image-link',{method:'POST',body:{url,remote_request_acknowledged:true}})).image_data_url});
